mapper.select:
SELECT f.id, f.origin_name, f.store_name, f.file_path, f.ext, f.file_size, f.content_type, f.uploader_id, f.create_time, f.status, CASE WHEN f.ext IN ('pdf', 'doc', 'docx') THEN '文档' WHEN f.ext IN ('jpg', 'png') THEN '图片' WHEN f.ext = 'zip' THEN '压缩包' ELSE '其他' END AS category, (SELECT COUNT(*) FROM download_log d WHERE d.file_id = f.id) AS download_count FROM file_info f WHERE f.uploader_id = #{uploaderId} AND f.status <> 0
AND CASE WHEN f.ext IN ('pdf', 'doc', 'docx') THEN '文档' WHEN f.ext IN ('jpg', 'png') THEN '图片' WHEN f.ext = 'zip' THEN '压缩包' ELSE '其他' END = #{category}
ORDER BY f.create_time DESC

mapper.update:
UPDATE file_info
SET status = #{status}
WHERE id = #{id} AND uploader_id = #{uploaderId}
